    '    await page.waitForFunction(() => { const imgs=[...document.images].filter((img)=>{const r=img.getBoundingClientRect();return r.width>0&&r.height>0&&r.top<innerHeight&&r.bottom>0&&r.left<innerWidth&&r.right>0});return imgs.length>0&&imgs.every((img)=>img.currentSrc&&img.complete&&img.naturalWidth>0); }, { timeout: 15000 });',
    '    const viewportAssets=await page.evaluate(()=>[...document.images].filter((img)=>{const r=img.getBoundingClientRect();return r.width>0&&r.height>0&&r.top<innerHeight&&r.bottom>0&&r.left<innerWidth&&r.right>0}).map((img)=>({key:img.closest("[data-pick]")?.getAttribute("data-pick")||"",src:img.currentSrc,bytes:window.__scaleBlobBytes.get(img.currentSrc)})));',
    '    const visibleKeys=new Set(viewportAssets.map((asset)=>asset.key).filter(Boolean));const transfers=[...reqs.values()].filter((r)=>{try{const u=new (require("node:url").URL)(r.url);return u.pathname==="/api/studio/portrait"&&visibleKeys.has(u.searchParams.get("kind")+":"+u.searchParams.get("id"));}catch{return false}});await Promise.all(transfers.map((r)=>r.bodyRead));const matchedKeys=new Set(transfers.map((r)=>{const u=new (require("node:url").URL)(r.url);return u.searchParams.get("kind")+":"+u.searchParams.get("id")}));const missingKeys=[...visibleKeys].filter((key)=>!matchedKeys.has(key));const missingBodies=transfers.filter((r)=>!Number.isSafeInteger(r.bodyBytes)||r.bodyBytes<=0);if(visibleKeys.size&&transfers.length&&missingKeys.length===0&&missingBodies.length===0){metric("library.first_viewport_art_bytes",transfers.reduce((sum,r)=>sum+r.bodyBytes,0),"bytes",transfers.length,"Decoded response-body bytes for every completed /api/studio/portrait delivery keyed to a visible data-pick card; counts duplicate/alias transfers independently even when art-cache object URLs converge.");const resident=new Map(viewportAssets.filter((asset)=>Number.isSafeInteger(asset.bytes)&&asset.bytes>0).map((asset)=>[asset.src,asset.bytes]));if(resident.size===new Set(viewportAssets.map((asset)=>asset.src)).size)metric("library.first_viewport_resident_art_bytes",[...resident.values()].reduce((sum,bytes)=>sum+bytes,0),"bytes",resident.size,"Distinct current viewport art-cache Blob sizes; resident-memory observation, separate from delivered transfer budget.");}else{missing.push("library.first_viewport_art_bytes");failures.push("visible portrait delivery evidence incomplete: "+missingKeys.length+" card keys without a request, "+missingBodies.length+" bodies without decoded byte counts, "+visibleKeys.size+" visible cards, "+transfers.length+" deliveries");}',
    '    push("Library ready (every deck listed)", libraryMs + " ms");',
